import java.util.*;

public class Main {
    // 返回 LinkedHashMap 保证插入顺序；不匹配返回 null
    static Map<String,String> match(String template, String path){
        String[] tp = template.split("/");
        String[] pp = path.split("/");
        if (tp.length != pp.length) return null;
        Map<String,String> vars = new LinkedHashMap<>();
        for (int i = 0; i < tp.length; i++){
            if (tp[i].startsWith("{") && tp[i].endsWith("}")){
                vars.put(tp[i].substring(1, tp[i].length()-1), pp[i]);
            } else if (!tp[i].equals(pp[i])){
                return null;
            }
        }
        return vars;
    }

    public static void main(String[] args){
        System.out.println(match("/users/{id}/posts/{pid}", "/users/7/posts/99"));
        System.out.println(match("/users/{id}", "/posts/7"));
    }
}
